; Menu Character Set Setup
; $1c2f-$1c61

; Sets the border black and blanks the screen ($d011 = $0b). With the character ROM visible, it runs menu_charset_script (charset at $5000). Then it selects screen $5c00 and charset $5000 ($d018 = $74) in VIC bank 1 ($dd00).
build_menu_charset
        lda #$00
        sta EXTCOL
        lda #$0b
        sta SCROLY                      ; $d011: yScroll 3, rows 25, rasterBit8 0
        sei
        lda R6510
        pha
        and #$fb
        sta R6510
        lda #$f8
        ldy #$1e
        jsr run_script
        pla
        sta R6510
        lda #$74
        sta VMCSB                       ; $d018: screenOffset $1c00, characterOffset $1000, bitmapOffset $0000
        lda CI2DDRA
        ora #$03
        sta CI2DDRA
        lda CI2PRA
        and #$fe
        sta CI2PRA
        cli
        rts
